style.css:
@-moz-document url-prefix("https://www.youtube.com") {
/* ========================================
     CSS VARIABLES - Customize colors here
     ======================================== */
  :root {
    /* Accent colors */
    --accent: #56CCF2;
    --accent-strong: #2AA7E0;

    /* Backgrounds */
    --bg: #0f1720;
    --bg-alt: rgba(255, 255, 255, 0.03);
    --card: #0b1115;

    /* Text & neutrals */
    --muted: #9aa4ad;
    --text: #e6eef6;

    /* Design tokens */
    --radius: 10px;
    --shadow: 0 6px 18px rgba(2, 6, 12, 0.6);
    --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Light mode override (optional) */
  .light-mode {
    --bg: #f8f9fb;
    --bg-alt: rgba(0, 0, 0, 0.04);
    --card: #ffffff;
    --muted: #5f6368;
    --text: #0f1720;
    --shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
  }

  /* ========================================
     GLOBAL RESETS & BASE
     ======================================== */
  html, body {
    background-color: var(--bg) !important;
    color: var(--text) !important;
    font-family: 'Roboto', 'Arial', sans-serif !important;
    -webkit-font-smoothing: antialiased;
  }

  * {
    transition: background-color var(--transition), color var(--transition), transform var(--transition), box-shadow var(--transition) !important;
  }

  @media (prefers-reduced-motion: reduce) {
    * {
      transition: none !important;
    }
  }

  /* ========================================
     TOP BAR / MASTHEAD - Frosted glass
     ======================================== */
  ytd-masthead,
  #masthead-container,
  #masthead {
    background: rgba(15, 23, 32, 0.75) !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.4) !important;
    border-bottom: 1px solid var(--bg-alt) !important;
  }

  ytd-searchbox input,
  #search-input input {
    background: var(--card) !important;
    color: var(--text) !important;
    border: 1px solid var(--bg-alt) !important;
    border-radius: var(--radius) !important;
    padding: 10px 16px !important;
    font-size: 14px !important;
  }

  ytd-searchbox input:focus,
  #search-input input:focus {
    border-color: var(--accent) !important;
    outline: 2px solid var(--accent) !important;
    outline-offset: 2px !important;
  }

  #search-icon-legacy,
  #voice-search-button,
  ytd-button-renderer button {
    background: var(--card) !important;
    color: var(--text) !important;
    border-radius: var(--radius) !important;
  }

  /* ========================================
     SIDEBAR - Frosted glass
     ======================================== */
  ytd-guide-renderer,
  #guide-inner-content,
  ytd-mini-guide-renderer {
    background: rgba(15, 23, 32, 0.8) !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    color: var(--muted) !important;
    border-radius: 8px !important;
    margin: 2px 8px !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover,
  ytd-guide-entry-renderer[active],
  ytd-mini-guide-entry-renderer[active] {
    background: var(--bg-alt) !important;
    color: var(--text) !important;
  }

  /* ========================================
     MAIN CONTENT AREA
     ======================================== */
  ytd-app,
  ytd-page-manager,
  #content,
  ytd-browse,
  ytd-two-column-browse-results-renderer {
    background-color: var(--bg) !important;
  }

  /* ========================================
     VIDEO THUMBNAILS - Rounded + hover lift
     ======================================== */
  ytd-thumbnail,
  yt-img-shadow,
  ytd-thumbnail a,
  ytd-thumbnail img,
  ytd-playlist-thumbnail img,
  #img {
    border-radius: var(--radius) !important;
    overflow: hidden !important;
    box-shadow: var(--shadow) !important;
  }

  ytd-thumbnail:hover img,
  ytd-rich-item-renderer:hover ytd-thumbnail img,
  ytd-grid-video-renderer:hover ytd-thumbnail img,
  ytd-video-renderer:hover ytd-thumbnail img {
    transform: translateY(-4px) !important;
    box-shadow: 0 12px 24px rgba(2, 6, 12, 0.8) !important;
  }

  /* ========================================
     VIDEO CARDS / GRID ITEMS
     ======================================== */
  ytd-rich-grid-renderer,
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer,
  ytd-compact-video-renderer {
    background: transparent !important;
  }

  ytd-rich-item-renderer #content,
  ytd-video-renderer #dismissible,
  ytd-grid-video-renderer #dismissible {
    background: var(--card) !important;
    border-radius: var(--radius) !important;
    padding: 12px !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3) !important;
  }

  ytd-rich-item-renderer:hover #content,
  ytd-video-renderer:hover #dismissible,
  ytd-grid-video-renderer:hover #dismissible {
    background: var(--bg-alt) !important;
    box-shadow: var(--shadow) !important;
  }

  /* ========================================
     VIDEO TITLES & META
     ======================================== */
  #video-title,
  ytd-video-renderer #video-title,
  ytd-grid-video-renderer #video-title {
    color: var(--text) !important;
    font-weight: 500 !important;
    font-size: 14px !important;
    line-height: 1.4 !important;
  }

  #video-title:hover {
    color: var(--accent) !important;
  }

  ytd-video-meta-block,
  #metadata-line,
  #metadata {
    color: var(--muted) !important;
    font-size: 12px !important;
  }

  yt-formatted-string[id="published-time-text"],
  yt-formatted-string.ytd-video-meta-block {
    color: var(--muted) !important;
  }

  /* ========================================
     VIDEO PLAYER PAGE
     ======================================== */
  ytd-watch-flexy,
  #player-container-outer,
  #player-container {
    background: var(--card) !important;
  }

  #player-theater-container,
  .html5-video-player {
    border-radius: var(--radius) !important;
    overflow: hidden !important;
  }

  ytd-watch-metadata {
    background: var(--card) !important;
    border-radius: var(--radius) !important;
    padding: 16px !important;
    margin-top: 12px !important;
  }

  #title h1,
  ytd-watch-metadata h1 {
    color: var(--text) !important;
    font-weight: 600 !important;
  }

  ytd-video-owner-renderer,
  #owner {
    background: var(--bg-alt) !important;
    border-radius: var(--radius) !important;
    padding: 12px !important;
  }

  /* ========================================
     SUBSCRIBE BUTTON - Accent gradient
     ======================================== */
  ytd-subscribe-button-renderer button,
  ytd-button-renderer.ytd-subscribe-button-renderer button,
  .ytd-subscribe-button-renderer[subscribed] button {
    background: linear-gradient(135deg, var(--accent), var(--accent-strong)) !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: calc(var(--radius) * 2) !important;
    padding: 10px 24px !important;
    font-weight: 600 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
    box-shadow: 0 4px 12px rgba(86, 204, 242, 0.4) !important;
  }

  ytd-subscribe-button-renderer button:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 6px 16px rgba(86, 204, 242, 0.6) !important;
  }

  ytd-subscribe-button-renderer button:focus {
    outline: 2px solid var(--accent) !important;
    outline-offset: 2px !important;
  }

  /* ========================================
     COMMENTS SECTION
     ======================================== */
  #comments,
  ytd-comments,
  ytd-item-section-renderer#sections {
    background: var(--card) !important;
    border-radius: var(--radius) !important;
    padding: 20px !important;
    margin-top: 16px !important;
  }

  ytd-comment-renderer,
  ytd-comment-thread-renderer {
    background: var(--bg-alt) !important;
    border-radius: 8px !important;
    padding: 12px !important;
    margin-bottom: 12px !important;
  }

  #comment #content-text,
  ytd-comment-renderer #content-text {
    color: var(--text) !important;
    line-height: 1.6 !important;
  }

  #author-text,
  ytd-comment-renderer #author-text {
    color: var(--accent) !important;
    font-weight: 500 !important;
  }

  /* ========================================
     CHANNEL HEADER
     ======================================== */
  ytd-c4-tabbed-header-renderer,
  ytd-channel-tagline-renderer {
    background: var(--card) !important;
    border-radius: var(--radius) !important;
    box-shadow: var(--shadow) !important;
  }

  #channel-header-container {
    background: linear-gradient(135deg, var(--card), var(--bg-alt)) !important;
  }

  /* ========================================
     DRAWER PANELS & POPOVERS
     ======================================== */
  tp-yt-paper-dialog,
  ytd-popup-container,
  ytd-menu-popup-renderer,
  tp-yt-iron-dropdown {
    background: var(--card) !important;
    border-radius: var(--radius) !important;
    box-shadow: var(--shadow) !important;
    border: 1px solid var(--bg-alt) !important;
  }

  ytd-menu-service-item-renderer,
  ytd-menu-navigation-item-renderer {
    color: var(--text) !important;
  }

  ytd-menu-service-item-renderer:hover,
  ytd-menu-navigation-item-renderer:hover {
    background: var(--bg-alt) !important;
  }

  /* ========================================
     FLOATING ACTION BUTTONS
     ======================================== */
  ytd-button-renderer[is-icon-button],
  yt-icon-button {
    background: var(--card) !important;
    border-radius: 50% !important;
    color: var(--text) !important;
  }

  ytd-button-renderer[is-icon-button]:hover,
  yt-icon-button:hover {
    background: var(--bg-alt) !important;
    transform: scale(1.1) !important;
  }

  /* ========================================
     SCROLLBARS - Custom styling
     ======================================== */
  ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
  }

  ::-webkit-scrollbar-track {
    background: var(--bg) !important;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--bg-alt) !important;
    border-radius: 5px !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--accent) !important;
  }
}
